"use strict";(globalThis.webpackChunkp_foundation||=[]).push([[4167],{2841(e,t,n){n.r(t),n.d(t,{default:()=>c,metadata:()=>a});var a=n(6520),r=n(4848),o=n(8453);const s={title:"OpenIX Beirut Is Now MANRS Compliant",description:"OpenIX Beirut has joined the MANRS IXP Programme, the global standard for routing security at Internet Exchange Points, with all five of its actions validated. The exchange has met the MANRS requirements since launch, and today commits publicly to remaining compliant and to helping its members do the same on their own networks.",slug:"OpenIXBeirutMANRS",authors:"jud",image:"https://assets.p.foundation/assets/ae3aeefb-9e06-4ef3-810c-dff4048b7527",hide_table_of_contents:!1,date:new Date("2026-09-15T17:00:00.000Z")},i={authorsImageUrls:[void 0]};function h(e){const t={a:"a",h2:"h2",li:"li",ol:"ol",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.a,{href:"/OpenIX/beirut",children:"OpenIX Beirut"})," is now a participant in the ",(0,r.jsx)(t.a,{href:"https://manrs.org/participant/019eccd4-bc10-786e-abfa-a13830c4f843",children:"MANRS IXP Programme"}),", with all five of its actions implemented. MANRS, the Mutually Agreed Norms for Routing Security, is the global initiative that sets out what a responsible network or exchange must do to keep the internet's routing system honest, and its IXP Programme is the version of that standard written for Internet Exchange Points. OpenIX Beirut has met those requirements since the day its first port came up. What is new today is that MANRS has reviewed our setup and validated it, and that we are making a public commitment to keep it that way, alongside the exchanges that carry much of the world's traffic."]}),"\n",(0,r.jsx)(t.p,{children:"The internet has no central authority that decides which network may announce which addresses. Every router takes the routes its neighbours give it largely on trust, and that trust is what route hijacks, route leaks, and address spoofing exploit. A single misconfigured announcement can pull a bank's traffic across a border, take a country's news sites offline, or blackhole a hospital's connectivity, and the network that caused it often never notices. As MANRS puts it, these incidents are global in scale, with one operator's routing problems cascading to impact others. The fix is not one clever device but a set of practices everyone agrees to keep, and an exchange, where dozens of networks meet on one fabric, is where those practices matter most."}),"\n",(0,r.jsx)(t.h2,{id:"why-it-matters-for-lebanon",children:"Why It Matters for Lebanon"}),"\n",(0,r.jsxs)(t.p,{children:["OpenIX Beirut was built to keep Lebanon's traffic at home. Sixteen months after launch, ",(0,r.jsx)(t.a,{href:"/OpenIX/beirut/networks",children:"45 networks"})," trade traffic across it, and a large share of what the country's users do each day now stays within local reach. That success raises the stakes. When most of a country's traffic meets at one exchange, a bad route announced there travels further and faster than it ever could through a dozen separate transit paths. The exchange has to be the place where a mistake stops, not the place it spreads from."]}),"\n",(0,r.jsx)(t.p,{children:"Routing security also has a particular weight in a country whose international links are scarce and fragile. A hijack that drags Lebanese traffic through the wrong continent costs latency, costs the foreign currency that pays for international transit, and, when it lands on the wrong network, can expose that traffic to interception. Filtering at the exchange is how we make sure the shortest path is also a trustworthy one."}),"\n",(0,r.jsx)(t.h2,{id:"what-the-programme-asks-of-an-exchange",children:"What the Programme Asks of an Exchange"}),"\n",(0,r.jsxs)(t.p,{children:["MANRS began as ",(0,r.jsx)(t.a,{href:"https://manrs.org/wp-content/uploads/2018/04/MANRS-IXP-factsheet_FINAL-online.pdf",children:"four actions for network operators"}),": filtering, anti-spoofing, coordination, and global validation. Exchanges sit in a different place in the routing system, so the community wrote a related but separate set of five actions for IXPs, built on the idea that an exchange can turn its members into a safe neighborhood. OpenIX Beirut's ",(0,r.jsx)(t.a,{href:"https://manrs.org/participant/019eccd4-bc10-786e-abfa-a13830c4f843",children:"MANRS listing"})," records all five as implemented:"]}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Filtering of route announcements."})," The exchange's route servers validate what they receive and drop announcements that are not legitimately the peer's to make."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Assistance to members."})," The exchange helps its members keep accurate routing information in the IRR and RPKI, and helps them implement the MANRS network operator actions on their own networks."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Protection of the peering platform."})," The fabric itself is kept safe from misconfiguration and abuse at the link layer."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Global operational communication and coordination."})," Members and outside operators can reach the right people, and there is a process for handling incidents and disputes."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Monitoring and debugging tools for members."})," Networks can see what the exchange is doing with their routes and why."]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Here is what each of them looks like at OpenIX Beirut."}),"\n",(0,r.jsx)(t.h2,{id:"every-route-checked-before-it-moves",children:"Every Route, Checked Before It Moves"}),"\n",(0,r.jsxs)(t.p,{children:["Our ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/routeServer",children:"route servers"})," validate every prefix a participant announces before it reaches any other peer. The sequence is deliberate and strict. Prefixes that are too specific or too general are dropped, as are bogons and announcements carrying a bogon ASN. The first AS in the path must be the peer's own, the next hop must be the peer's own address, and any path that carries a transit-free network's ASN is rejected as a likely leak. Then the checks that MANRS is really about: the origin AS and the prefix must both be covered by the member's registered IRR AS-SET, and every route is checked against RPKI. ",(0,r.jsx)(t.strong,{children:"RPKI-valid routes are accepted, RPKI-invalid routes are dropped"}),", and routes with no RPKI record fall back to IRR filtering. Per-participant prefix limits sit on top of all of it, so no single network can flood the exchange with routes, by accident or otherwise. Repeated leaks or bogon announcements are a violation of our ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/security",children:"peering policy"}),", not a nuisance we tolerate."]}),"\n",(0,r.jsx)(t.p,{children:"None of this is new to OpenIX. These filters have been in place since the exchange came up, because we would not run a route server any other way, and the exchange has been compliant with the MANRS requirements from the start. Still, there is a difference between meeting a standard and having it confirmed. MANRS has now reviewed how OpenIX Beirut is built and run and validated it against the programme, action by action. That independent check is worth having on its own, and it gives anyone, member or not, a way to look up OpenIX Beirut and know exactly what standard it holds itself to."}),"\n",(0,r.jsx)(t.h2,{id:"a-fabric-that-protects-itself",children:"A Fabric That Protects Itself"}),"\n",(0,r.jsxs)(t.p,{children:["Route servers are only part of the story. An exchange is also a shared Layer 2 network, and the mistakes that cause the most outages at exchanges are often not routing mistakes at all. OpenIX runs a default-deny policy on the fabric. Every port is ",(0,r.jsx)(t.a,{href:"/OpenIX/technicalStandards",children:"locked to a single MAC address"}),", so a device that should not be on the exchange cannot speak on it. Storm control caps broadcast and multicast floods before they touch other members. Control-plane access lists drop the protocols that have no business on a peering LAN, from spanning tree to rogue router advertisements to DHCP, and anything not explicitly permitted is filtered. All of it is written down in our published ",(0,r.jsx)(t.a,{href:"/OpenIX/security/network",children:"network security measures"}),", and our NOC watches the fabric for anomalies around the clock."]}),"\n",(0,r.jsx)(t.h2,{id:"reachable-and-accountable",children:"Reachable, and Accountable"}),"\n",(0,r.jsxs)(t.p,{children:["Routing security is a team sport, and most of the work happens between people rather than between routers. OpenIX Beirut publishes its operational contacts and its full list of connected networks, is listed on ",(0,r.jsx)(t.a,{href:"https://www.peeringdb.com/ix/4727",children:"PeeringDB"}),", and publishes its member list in the standard IX-F format so that tools across the industry can see who peers here. When something does go wrong, members have a published ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/etiquette",children:"etiquette"})," and a ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/disputes",children:"disputes process"})," to fall back on, and the exchange follows an SLA-backed ",(0,r.jsx)(t.a,{href:"/OpenIX/sla/incidentResponse",children:"incident response procedure"})," to coordinate with the affected members and with the wider operator community. An operator on the other side of the world who sees a bad route from a Beirut network knows exactly who to call."]}),"\n",(0,r.jsx)(t.h2,{id:"see-what-the-exchange-sees",children:"See What the Exchange Sees"}),"\n",(0,r.jsxs)(t.p,{children:["When a route server rejects a prefix, it does not do so silently. Each rejected route is tagged with a large community that records exactly why it was dropped, and members can read those reasons in the looking glass inside the ",(0,r.jsx)(t.a,{href:"/updates/OpenIXBeirutOneYearLater",children:"P Foundation Console"}),", the same place a member already sees its traffic and its peers. The ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/routeServer",children:"BGP community controls"})," on the route servers are fully documented, so a member can steer and debug its own policy without a ticket, and the exchange's ",(0,r.jsx)(t.a,{href:"/OpenIX/beirut/traffic",children:"traffic statistics"})," are public. More is on the way to the console: route visibility, BGP session management, and IXP Watch route-health monitoring."]}),"\n",(0,r.jsx)(t.h2,{id:"the-part-we-ask-of-you",children:"The Part We Ask of You"}),"\n",(0,r.jsx)(t.p,{children:"Action 2 is the one no exchange can complete alone. Our route servers filter what crosses them, but bilateral sessions between members do not pass through our filters, and a member's own customers and transit are outside our reach entirely. Routing security is only as strong as the network at the far end of every link."}),"\n",(0,r.jsxs)(t.p,{children:["So this is a commitment and an invitation. The commitment is ours: our engineers will help any member register and maintain its IRR objects and RPKI ROAs, and will work hands-on with any member that wants to implement the four MANRS network operator actions, filtering, anti-spoofing, coordination, and global validation. The invitation is to take that step and join the ",(0,r.jsx)(t.a,{href:"https://manrs.org",children:"MANRS Network Operator Programme"})," yourself. The actions are the ones our own ",(0,r.jsx)(t.a,{href:"/OpenIX/peering/security",children:"peering security policy"})," already expects of you: filter the routes you accept and announce, prevent traffic with spoofed source addresses from leaving your network, keep your contact details current in PeeringDB, and publish RPKI ROAs and IRR objects for the prefixes you originate, so that every exchange and transit provider on the internet can validate your routes the way ours already does."]}),"\n",(0,r.jsx)(t.p,{children:"The point of OpenIX was never just to move traffic. It was to give Lebanon an internet it could rely on, and reliability includes trust in where every packet is going. That is why we are making this commitment in public: OpenIX Beirut will remain MANRS compliant. As the exchange grows, as new members connect, and as the programme's requirements evolve, we will keep the filters strict, keep the platform protected, keep our contacts and tools current, and keep helping our members meet the same bar. Today that trust has a standard behind it, an independent validation to back it, and our word that it will stay that way."})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}n.d(t,["assets",0,i,"contentTitle",0,"OpenIX Beirut Is Now MANRS Compliant","frontMatter",0,s,"toc",0,[{value:"Why It Matters for Lebanon",id:"why-it-matters-for-lebanon",level:2},{value:"What the Programme Asks of an Exchange",id:"what-the-programme-asks-of-an-exchange",level:2},{value:"Every Route, Checked Before It Moves",id:"every-route-checked-before-it-moves",level:2},{value:"A Fabric That Protects Itself",id:"a-fabric-that-protects-itself",level:2},{value:"Reachable, and Accountable",id:"reachable-and-accountable",level:2},{value:"See What the Exchange Sees",id:"see-what-the-exchange-sees",level:2},{value:"The Part We Ask of You",id:"the-part-we-ask-of-you",level:2}]])},8453(e,t,n){n.d(t,{R:()=>s,x:()=>i});var a=n(6540);const r={},o=a.createContext(r);function s(e){const t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),a.createElement(o.Provider,{value:t},e.children)}},6520(e){e.exports=JSON.parse('{"permalink":"/updates/OpenIXBeirutMANRS","source":"@site/updates/2026-09-15-OpenIXBeirutMANRS.md","title":"OpenIX Beirut Is Now MANRS Compliant","description":"OpenIX Beirut has joined the MANRS IXP Programme, the global standard for routing security at Internet Exchange Points, with all five of its actions validated. The exchange has met the MANRS requirements since launch, and today commits publicly to remaining compliant and to helping its members do the same on their own networks.","date":"2026-09-15T17:00:00.000Z","tags":[],"readingTime":8.16,"hasTruncateMarker":true,"authors":[{"name":"Jud Saoud","title":"COO of P Foundation","email":"jud@p.foundation","imageURL":"https://github.com/judsd.png","key":"jud","page":null}],"frontMatter":{"title":"OpenIX Beirut Is Now MANRS Compliant","description":"OpenIX Beirut has joined the MANRS IXP Programme, the global standard for routing security at Internet Exchange Points, with all five of its actions validated. The exchange has met the MANRS requirements since launch, and today commits publicly to remaining compliant and to helping its members do the same on their own networks.","slug":"OpenIXBeirutMANRS","authors":"jud","image":"https://assets.p.foundation/assets/ae3aeefb-9e06-4ef3-810c-dff4048b7527","hide_table_of_contents":false,"date":"2026-09-15T17:00:00.000Z"},"unlisted":false,"lastUpdatedAt":1789482103000,"nextItem":{"title":"OpenIX Beirut: One Year Later","permalink":"/updates/OpenIXBeirutOneYearLater"}}')}}]);